assignment.solutionCode:
class Ship:
    def __init__(self, health, attack_power):
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

    def is_destroyed(self):
        return self.health == 0


class Alien:
    def __init__(self, health, attack_power):
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

    def is_destroyed(self):
        return self.health == 0


def battle_round(ship, alien):
    ship.take_damage(alien.attack_power)
    alien.take_damage(ship.attack_power)
    print(f"Ship HP: {ship.health} | Alien HP: {alien.health}")
